    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint dummy) public payable {
        bool reverted;
        c.finishDistribution(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        bool distFinished = c.distributionFinished(); if (__ESBMC_reverted()) return;
        assert(reverted || distFinished);
    }

    receive() external payable {}
}

