pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    NewIntelTechMedia c;

    function setUp() public {
        c = new NewIntelTechMedia();
    }

    function _run(uint256 dummy) internal {
        bool reverted;
        try c.finishDistribution() { reverted = false; } catch { reverted = true; }
        bool distFinished;
        try c.distributionFinished() returns (bool __r) { distFinished = __r; } catch { return; }
        assertTrue(reverted || distFinished);
    }

    function testFuzz_run(uint256 dummy) public {
        _run(dummy);
    }

    receive() external payable {}
}
